import{z as n,x as C,o as B,c as i,q as s,j as t,D as A,d as e,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"RDMA","description":"","frontmatter":{"title":"RDMA","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hpc-rdma.md","filePath":"cs/hpc-rdma.md","lastUpdated":1791063341000}'),D={name:"cs/hpc-rdma.md"};function d(p,E,P,R,m,F){const r=C("Mermaid");return B(),i("div",null,[E[2]||(E[2]=s('<h1 id="rdma" tabindex="-1">RDMA <a class="header-anchor" href="#rdma" aria-label="Permalink to &quot;RDMA&quot;">​</a></h1><div class="epigraph"><p>内核旁路只绕开本机的栈；RDMA 把对端机器上的操作系统也从数据路径上请了出去。</p><footer>—— 据 IBTA InfiniBand 架构规范；rdma-core 文档整理</footer></div><p><a href="/cs/hpc-kernel-bypass">上一课</a>把本机协议栈从数据面拿掉，包直接进用户态缓冲；但两台机器之间，TCP 仍要在双方内核里各走一遍。<a href="/cs/rdma-os">RDMA 在 OS 中的位置</a>已在主干钉了骨架：内核管注册与 QP，数据 DMA 进用户内存。本课深化数据面本身：verbs 的双边与单边语义、注册内存的纪律、无损网络为什么是前提，以及完整的代价清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旁路之后，端到端延迟里还剩什么：对端的内核 TCP、两端的上下文切换、缓冲区之间的拷贝，以及丢包后以十毫秒计的重传。RDMA 把传输卸载进网卡：QP 状态与重传逻辑在硬件里执行，verbs 从用户态写门铃寄存器、不陷内核，DMA 直接读写两端注册过的内存。双向延迟落到微秒量级，CPU 近乎不参与。不这么做会错在哪：把 RDMA 当快版 socket，只用双边 SEND/RECV，每条消息都要对端先贴好接收缓冲，单边语义「对端 CPU 不参与」的收益全部丢失；或者内存注册完又交给会迁移页的子系统，DMA 写进的是失效页——这是正确性事故，不是性能问题。</p><p><span class="marginnote">直觉类比：双边 SEND/RECV 像寄快递，收件人必须先在家摆好空箱子，你才能一件一件寄；单边 WRITE 像拿着对方储物柜的钥匙（rkey）直接把货放进指定格子——对方不必在场，但钥匙给多了、给错了，就是安全与正确性事故。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象链一次建齐：保护域 PD → 注册内存 MR（钉页、取 lkey/rkey）→ 队列对 QP → 完成队列 CQ。收发：应用 post 一个 WR 进 SQ，网卡异步执行，从 CQ 轮询或等事件收割 CQE。语义分两族：SEND/RECV 双边，对端 RQ 必须预先贴好缓冲，逐条消耗；RDMA WRITE/READ 单边，发起方直接写读对端 MR，对端 CPU 全程不参与，完成通知靠约定——写完在末尾翻转标志，或补发一个 SEND 作信号。传输族三选：InfiniBand 走专用链路；RoCE v2 跑在 UDP/IP 上，靠 PFC 优先级流控与 ECN 把网络做成无损；iWARP 走 TCP。GPU 场景配 GPUDirect RDMA，网卡直接读写显存，省掉经主存的转运拷贝。</p>',8)),(B(),t(o,null,{default:A(()=>[l(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%20A%EF%BC%9Apost%20WR%22%5D%20--%3E%20NIC1%5B%22%E7%BD%91%E5%8D%A1%20A%EF%BC%9AQP%20%E7%A1%AC%E4%BB%B6%E6%89%A7%E8%A1%8C%22%5D%0A%20%20NIC1%20--%3E%7CDMA%20%E8%AF%BB%E5%86%99%7C%20MR1%5B%22MR%EF%BC%9A%E9%92%89%E4%BD%8F%E7%9A%84%E6%B3%A8%E5%86%8C%E9%A1%B5%22%5D%0A%20%20NIC1%20--%3E%20WIRE%5B%22%E6%97%A0%E6%8D%9F%E7%BD%91%E7%BB%9C%EF%BC%9APFC%2FECN%22%5D%0A%20%20WIRE%20--%3E%20NIC2%5B%22%E7%BD%91%E5%8D%A1%20B%EF%BC%9A%E6%8E%92%E5%BA%8F%E4%B8%8E%E9%87%8D%E4%BC%A0%22%5D%0A%20%20NIC2%20--%3E%7C%E5%8D%95%E8%BE%B9%20WRITE%20%E7%9B%B4%E5%86%99%7C%20MR2%5B%22%E5%AF%B9%E7%AB%AF%20MR%22%5D%0A%20%20NIC2%20--%3E%20CQ2%5B%22%E5%AF%B9%E7%AB%AF%20CQ%EF%BC%9A%E6%8C%89%E7%BA%A6%E5%AE%9A%E9%80%9A%E7%9F%A5%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"CPU 不参与仍不失序的机制在于：有序、重传、流控全部在网卡固件里，QP 状态机硬件执行；无损网络把「丢包后重传」换成「上游按优先级暂停」，PFC 在链路层掐住，ECN 与 DC-QCN 把拥塞反馈回发送端。注册内存是钉住的账目：物理页不可回收，大 MR 直接吃掉可用内存，注册与撤销本身昂贵，池化与长期注册因此是常态。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：注册一块 100 GB 的 MR，等于把 100 GB 物理内存永久钉死——机器若是 256 GB，剩下的给其他进程与页缓存的空间立刻少去近四成。所以 MR 建一次、池化复用是常态，按消息频繁注册/撤销会把收益吃光。"),e("量级锚点：同机房双向延迟在厂商公开指标里约 1–2 μs，比内核 TCP 的数十微秒低一个数量级；代价清单的另一头是 PFC 的死锁与头阻塞——优先级配置错配时，无损网络会自己把自己拥塞死。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"lkey/rkey 是 DMA 的地址翻译凭据：网卡拿 key 访问物理页，不经页表。THP 合并、内存迁移、容器换宿主都会让「注册过的页」位移，生产事故常出在注册之后又把同一块内存交给会移动页的路径。")],-1)),E[7]||(E[7]=a("p",null,"双边与单边语义差在哪一步？把对端 CPU 的参与时机并排看：",-1)),(B(),t(o,null,{default:A(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20D%5B%22%E5%8F%8C%E8%BE%B9%20SEND%2FRECV%22%5D%0A%20%20%20%20A1%5B%22A%EF%BC%9Apost%20SEND%22%5D%20--%3E%20B1%5B%22B%20%E7%BD%91%E5%8D%A1%E6%8C%89%20RQ%20%E6%94%B6%22%5D%0A%20%20%20%20B1%20--%3E%20B2%5B%22B%20CPU%20%E9%A2%84%E5%85%88%E8%B4%B4%E7%BC%93%E5%86%B2%E3%80%81%E9%80%90%E6%9D%A1%E6%B6%88%E8%80%97%22%5D%0A%20%20end%0A%20%20subgraph%20S%5B%22%E5%8D%95%E8%BE%B9%20RDMA%20WRITE%22%5D%0A%20%20%20%20A2%5B%22A%EF%BC%9Apost%20WRITE%20%E5%B8%A6%20rkey%22%5D%20--%3E%20B3%5B%22B%20%E7%BD%91%E5%8D%A1%E7%9B%B4%E5%86%99%E5%AF%B9%E7%AB%AF%20MR%22%5D%0A%20%20%20%20B3%20--%3E%20B4%5B%22B%20CPU%20%E5%85%A8%E7%A8%8B%E4%B8%8D%E5%8F%82%E4%B8%8E%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22A%20%E6%8C%89%E7%BA%A6%E5%AE%9A%E8%87%AA%E5%8F%96%E9%80%9A%E7%9F%A5%EF%BC%9A%E7%BF%BB%E8%BD%AC%E6%A0%87%E5%BF%97%E6%88%96%E8%A1%A5%E5%8F%91%20SEND%22%5D%0A%20%20end%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写集合通信库的拓扑与路由（那是 NCCL 内部的事），不写 NVMe-oF 存储路径，不重讲<a href="/cs/zero-copy-network">零拷贝网络</a>已钉的钉页与 DMA 原理。下一课回到通用路径：零拷贝与旁路省下的时间，要靠测得准才能兑现成结论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>verbs 数据面：PD/MR/QP/CQ，用户态门铃，传输由网卡硬件执行。</li><li>双边 SEND/RECV 要对端贴缓冲；单边 WRITE/READ 让对端 CPU 离场，通知靠约定。</li><li>无损网络（PFC/ECN）是 RoCE 的前提，同时引入死锁与头阻塞的新风险。</li><li>注册内存是钉住的账：页不可回收、注册昂贵、GPU 要 GPUDirect 才不绕主存。</li><li>出处：IBTA InfiniBand 架构规范；rdma-core 文档；厂商公开延迟指标。</li></ul><p><span class="marginnote">常见误区：把「无损网络」理解成「永不拥塞」。PFC 做的其实是让上游在交换机队列将满时先暂停发送——拥塞没有消失，只是从「丢包重传」换成了「整条链路踩刹车」。优先级配错时，互相等待会演成死锁，网络自己把自己掐停。</span></p>',5))])}const c=n(D,[["render",d]]);export{M as __pageData,c as default};
